  "implementation": "def solve(case):
    wti = case['word_token_indices']
    wl = case['word_labels']
    tc = case['token_count']
    if len(wti) != len(wl):
        raise ValueError('Mismatch between word_token_indices and word_labels lengths')
    token_label = [None] * tc
    for indices, label in zip(wti, wl):
        for idx in indices:
            if not (0 <= idx < tc):
                raise ValueError(f'Token index {idx} out of range')
            if token_label[idx] is not None:
                raise ValueError(f'Token index {idx} overlapped')
            token_label[idx] = label
    for i, lbl in enumerate(token_label):
        if lbl is None:
            raise ValueError(f'Token index {i} uncovered')
    token_labels = [int(lbl) for lbl in token_label]
    retained_indices = [i for i, lbl in enumerate(token_labels) if lbl == 1]
    return {'token_labels': token_labels, 'retained_indices': retained_indices}"
